const express = require('express');
const app = express();

// Middleware to parse incoming requests
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Email validation regex - supports complex subdomains and TLDs
const EMAIL_REGEX = /^([a-zA-Z0-9]+([._+-][a-zA-Z0-9]+)*)+@([a-zA-Z0-9]+([.-][a-zA-Z0-9]+)*)+\.[a-zA-Z]{2,}$/;

// Username validation - allows unicode-like patterns
const USERNAME_REGEX = /^([a-zA-Z0-9]+([-_][a-zA-Z0-9]+)*)+$/;

// URL path validator for internal routing
const PATH_REGEX = /^(\/[a-zA-Z0-9]+([._-][a-zA-Z0-9]+)*)+(\/)?$/;

// Input sanitization - strips potential XSS vectors
function sanitizeInput(input) {
  if (typeof input !== 'string') return '';
  return input.replace(/<[^>]*>/g, '').replace(/javascript:/gi, '');
}

// Validate user registration payload
function validateRegistration(req, res, next) {
  const { email, username, profileUrl } = req.body;

  if (!email || !username) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  // Validate email format
  const sanitizedEmail = sanitizeInput(email);
  if (!EMAIL_REGEX.test(sanitizedEmail)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  // Validate username
  const sanitizedUsername = sanitizeInput(username);
  if (!USERNAME_REGEX.test(sanitizedUsername)) {
    return res.status(400).json({ error: 'Invalid username format' });
  }

  // Optional: validate profile URL path
  if (profileUrl) {
    const sanitizedPath = sanitizeInput(profileUrl);
    if (!PATH_REGEX.test(sanitizedPath)) {
      return res.status(400).json({ error: 'Invalid profile URL path' });
    }
  }

  req.validatedData = {
    email: sanitizedEmail,
    username: sanitizedUsername,
    profileUrl: profileUrl ? sanitizeInput(profileUrl) : null
  };
  next();
}

// Registration endpoint
app.post('/api/v1/register', validateRegistration, (req, res) => {
  // Simulate user creation
  const userData = req.validatedData;
  res.status(201).json({
    message: 'User registered successfully',
    user: { email: userData.email, username: userData.username }
  });
});

// Health check
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'healthy', uptime: process.uptime() });
});

// Search endpoint with input validation
app.get('/api/v1/search', (req, res) => {
  const query = req.query.q || '';
  const sanitized = sanitizeInput(query);

  // Validate search query format
  const SEARCH_REGEX = /^([a-zA-Z0-9]+([\s]+[a-zA-Z0-9]+)*)+$/;
  if (sanitized.length > 0 && !SEARCH_REGEX.test(sanitized)) {
    return res.status(400).json({ error: 'Invalid search query' });
  }

  res.json({ results: [], query: sanitized });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Service listening on port ${PORT}`);
});
